// What an imported customer looks like. To import products instead, swap
// these fields: the review table, mapping and validation all read from here.

export type FieldId =
  'name' | 'email' | 'company' | 'country' | 'plan' | 'seats'

export interface Field {
  id: FieldId
  label: string
  required?: boolean
  /** CSV headers that map to this field automatically, lowercased */
  aliases: string[]
  /** Returns an error message, or null when the value is fine */
  validate: (value: string) => string | null
  /** The value that gets imported */
  normalize: (value: string) => string | number | null
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/
export const plans = ['Free', 'Pro', 'Enterprise'] as const

const text = (value: string) => value.trim() || null

export const fields: Field[] = [
  {
    id: 'name',
    label: 'Name',
    required: true,
    aliases: ['name', 'full name', 'customer', 'customer name', 'contact'],
    validate: (v) => (v.trim() ? null : 'Name is required'),
    normalize: text,
  },
  {
    id: 'email',
    label: 'Email',
    required: true,
    aliases: ['email', 'e mail', 'email address', 'e mail address', 'mail'],
    validate: (v) =>
      !v.trim()
        ? 'Email is required'
        : EMAIL.test(v.trim())
          ? null
          : 'Not a valid email address',
    normalize: (v) => v.trim().toLowerCase(),
  },
  {
    id: 'company',
    label: 'Company',
    aliases: ['company', 'organization', 'organisation', 'account', 'business'],
    validate: () => null,
    normalize: text,
  },
  {
    id: 'country',
    label: 'Country',
    aliases: ['country', 'country code'],
    validate: (v) =>
      !v.trim() || /^[a-z]{2}$/i.test(v.trim())
        ? null
        : 'Use a 2-letter country code, like US',
    normalize: (v) => v.trim().toUpperCase() || null,
  },
  {
    id: 'plan',
    label: 'Plan',
    required: true,
    aliases: ['plan', 'tier', 'subscription'],
    validate: (v) =>
      plans.some((p) => p.toLowerCase() === v.trim().toLowerCase())
        ? null
        : `Plan must be ${plans.join(', ').replace(/, (?=[^,]*$)/, ' or ')}`,
    normalize: (v) =>
      plans.find((p) => p.toLowerCase() === v.trim().toLowerCase()) ?? null,
  },
  {
    id: 'seats',
    label: 'Seats',
    aliases: ['seats', 'licenses', 'licences', 'users', 'quantity'],
    validate: (v) => {
      if (!v.trim()) return null
      const n = Number(v.trim().replace(/,/g, ''))
      return Number.isInteger(n) && n >= 1
        ? null
        : 'Seats must be a whole number of at least 1'
    },
    normalize: (v) => (v.trim() ? Number(v.trim().replace(/,/g, '')) : 1),
  },
]

export const fieldById = Object.fromEntries(
  fields.map((f) => [f.id, f]),
) as Record<FieldId, Field>

/** Emails that already belong to a customer in your workspace */
export const existingEmails = new Set(['ada@lovelace.dev', 'grace@navy.mil'])

export interface CsvData {
  headers: string[]
  rows: string[][]
}

/**
 * A small RFC 4180 parser: quoted fields, doubled quotes, line breaks inside
 * quotes, CRLF, and comma, semicolon or tab delimiters (whichever the header
 * row uses most). Blank lines are dropped and short rows padded.
 */
export function parseCsv(input: string): CsvData {
  const text = input.replace(/^\uFEFF/, '')
  const firstLine = text.slice(0, text.search(/\r?\n|$/))
  const delimiter = [',', ';', '\t'].reduce((best, d) =>
    firstLine.split(d).length > firstLine.split(best).length ? d : best,
  )

  const records: string[][] = []
  let record: string[] = []
  let field = ''
  let quoted = false

  for (let i = 0; i < text.length; i++) {
    const char = text[i]
    if (quoted) {
      if (char === '"' && text[i + 1] === '"') {
        field += '"'
        i++
      } else if (char === '"') quoted = false
      else field += char
    } else if (char === '"' && field === '') quoted = true
    else if (char === delimiter) {
      record.push(field)
      field = ''
    } else if (char === '\n' || char === '\r') {
      if (char === '\r' && text[i + 1] === '\n') i++
      record.push(field)
      records.push(record)
      record = []
      field = ''
    } else field += char
  }
  if (quoted) throw new Error('A quoted value is never closed.')
  if (field || record.length) {
    record.push(field)
    records.push(record)
  }

  const nonEmpty = records.filter((r) => r.some((v) => v.trim()))
  if (nonEmpty.length < 2) {
    throw new Error('The file needs a header row and at least one row of data.')
  }
  const [headers, ...rows] = nonEmpty
  return {
    headers: headers.map((h, i) => h.trim() || `Column ${i + 1}`),
    rows: rows.map((r) => headers.map((_, i) => r[i] ?? '')),
  }
}

import type { CsvData } from './csv'
import { existingEmails, fieldById, fields } from './schema'
import type { FieldId } from './schema'

/** The field each CSV column is imported into, by column index. null means "don't import". */
export type Mapping = (FieldId | null)[]

export interface Issue {
  /** invalid blocks the row; duplicate means the row would create a second copy */
  kind: 'invalid' | 'duplicate'
  message: string
}

export type RowStatus = 'ready' | 'invalid' | 'duplicate' | 'skipped'

export interface ReviewRow {
  id: string
  /** Line in the file, counting the header as line 1 */
  line: number
  cells: string[]
  /** Problems by CSV column index */
  issues: Partial<Record<number, Issue>>
  status: RowStatus
}

const words = (header: string) =>
  header
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()

/** Matches headers to fields by name, each field at most once */
export function autoMap(headers: string[]): Mapping {
  const used = new Set<FieldId>()
  return headers.map((header) => {
    const field = fields.find(
      (f) => !used.has(f.id) && f.aliases.includes(words(header)),
    )
    if (!field) return null
    used.add(field.id)
    return field.id
  })
}

/** Points a column at a field, taking the field away from any other column */
export function assign(
  mapping: Mapping,
  column: number,
  field: FieldId | null,
): Mapping {
  return mapping.map((current, i) =>
    i === column ? field : field && current === field ? null : current,
  )
}

export const missingRequired = (mapping: Mapping) =>
  fields.filter((f) => f.required && !mapping.includes(f.id))

/**
 * Validates every row against the mapping. Required fields that aren't mapped
 * are reported by missingRequired() instead, so they aren't repeated per row.
 */
export function review(
  csv: CsvData,
  mapping: Mapping,
  skipped: ReadonlySet<string>,
): ReviewRow[] {
  const emailColumn = mapping.indexOf('email')
  const firstLineByEmail = new Map<string, number>()

  return csv.rows.map((cells, index) => {
    const id = String(index)
    const line = index + 2
    const issues: Partial<Record<number, Issue>> = {}

    mapping.forEach((fieldId, column) => {
      if (!fieldId) return
      const message = fieldById[fieldId].validate(cells[column])
      if (message) issues[column] = { kind: 'invalid', message }
    })

    // Skipped rows don't claim an email, so skipping the first copy frees the second
    if (emailColumn >= 0 && !issues[emailColumn] && !skipped.has(id)) {
      const email = cells[emailColumn].trim().toLowerCase()
      const first = firstLineByEmail.get(email)
      if (existingEmails.has(email)) {
        issues[emailColumn] = {
          kind: 'duplicate',
          message: 'Already a customer in this workspace',
        }
      } else if (first !== undefined) {
        issues[emailColumn] = {
          kind: 'duplicate',
          message: `Same email as line ${first}`,
        }
      } else firstLineByEmail.set(email, line)
    }

    const kinds = Object.values(issues).map((i) => i!.kind)
    const status: RowStatus = skipped.has(id)
      ? 'skipped'
      : kinds.includes('invalid')
        ? 'invalid'
        : kinds.length
          ? 'duplicate'
          : 'ready'
    return { id, line, cells, issues, status }
  })
}

export type CustomerRecord = Partial<Record<FieldId, string | number | null>>

/** The normalized records that would be imported: ready rows only */
export function toRecords(
  rows: ReviewRow[],
  mapping: Mapping,
): CustomerRecord[] {
  return rows
    .filter((row) => row.status === 'ready')
    .map((row) => {
      const record: CustomerRecord = {}
      mapping.forEach((fieldId, column) => {
        if (fieldId)
          record[fieldId] = fieldById[fieldId].normalize(row.cells[column])
      })
      return record
    })
}

export type View = 'all' | 'attention' | 'ready' | 'skipped'

export const inView = (status: RowStatus, view: View) =>
  view === 'all' ||
  (view === 'attention'
    ? status === 'invalid' || status === 'duplicate'
    : status === view)

import { useState } from 'react'
import { CircleAlert, Copy } from 'lucide-react'

import { Input } from '#/components/ui/input'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '#/components/ui/tooltip'
import { cn } from '#/lib/utils'
import type { Issue } from './review'

// A cell of a mapped column. Problems are shown in place, and clicking the
// cell opens an input to fix the value. Any value is accepted on commit: the
// review runs again and the highlight goes away once the value is valid.
export function ReviewCell({
  value,
  issue,
  label,
  onCommit,
}: {
  value: string
  issue?: Issue
  /** e.g. "Email, line 4" */
  label: string
  onCommit: (value: string) => void
}) {
  const [draft, setDraft] = useState<string | null>(null)

  if (draft !== null) {
    const done = (save: boolean) => {
      if (save && draft !== value) onCommit(draft)
      setDraft(null)
    }
    return (
      <Input
        autoFocus
        value={draft}
        aria-label={label}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={() => done(true)}
        onKeyDown={(e) => {
          if (e.key === 'Enter') done(true)
          if (e.key === 'Escape') done(false)
        }}
        className="h-8 min-w-32"
      />
    )
  }

  const button = (
    <button
      type="button"
      onClick={() => setDraft(value)}
      aria-label={`${label}: ${value || 'empty'}${issue ? `. ${issue.message}` : ''}. Edit`}
      className={cn(
        'flex h-8 w-full min-w-24 items-center gap-1.5 rounded-md px-2 text-left outline-none hover:bg-muted focus-visible:ring-[3px] focus-visible:ring-ring/50',
        issue?.kind === 'invalid' &&
          'bg-destructive/10 text-destructive ring-1 ring-destructive/30 ring-inset hover:bg-destructive/15',
        issue?.kind === 'duplicate' &&
          'bg-amber-500/10 text-amber-700 ring-1 ring-amber-500/40 ring-inset hover:bg-amber-500/15 dark:text-amber-400',
      )}
    >
      <span className={cn('truncate', !value && 'italic opacity-70')}>
        {value || 'Empty'}
      </span>
      {issue ? (
        issue.kind === 'invalid' ? (
          <CircleAlert className="ml-auto size-3.5 shrink-0" />
        ) : (
          <Copy className="ml-auto size-3.5 shrink-0" />
        )
      ) : null}
    </button>
  )

  if (!issue) return button
  return (
    <Tooltip>
      <TooltipTrigger asChild>{button}</TooltipTrigger>
      <TooltipContent>{issue.message}</TooltipContent>
    </Tooltip>
  )
}

import {
  Select,
  SelectContent,
  SelectItem,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import { cn } from '#/lib/utils'
import { fields } from './schema'
import type { FieldId } from './schema'
import type { Mapping } from './review'

const SKIP = '__skip'

/** A column header: the CSV's own name, and the field it is imported into */
export function MappingSelect({
  header,
  column,
  mapping,
  onChange,
}: {
  header: string
  column: number
  mapping: Mapping
  onChange: (field: FieldId | null) => void
}) {
  const value = mapping[column]
  return (
    <div className="flex min-w-36 flex-col gap-1 py-2">
      <span
        className={cn(
          'truncate text-xs font-normal',
          value ? 'text-muted-foreground' : 'text-muted-foreground/70',
        )}
        title={header}
      >
        {header}
      </span>
      <Select
        value={value ?? SKIP}
        onValueChange={(v) => onChange(v === SKIP ? null : (v as FieldId))}
      >
        <SelectTrigger
          size="sm"
          aria-label={`Import column "${header}" as`}
          className={cn(
            'w-full bg-background font-medium',
            !value && 'border-dashed font-normal text-muted-foreground',
          )}
        >
          {/* Explicit text, so the hints inside the items stay out of the trigger */}
          <SelectValue>
            {value ? fields.find((f) => f.id === value)?.label : "Don't import"}
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          {fields.map((field) => {
            const elsewhere = mapping.findIndex(
              (f, i) => f === field.id && i !== column,
            )
            return (
              <SelectItem key={field.id} value={field.id}>
                {field.label}
                {field.required ? (
                  <span className="text-muted-foreground">required</span>
                ) : null}
                {elsewhere >= 0 ? (
                  <span className="text-muted-foreground">· moves here</span>
                ) : null}
              </SelectItem>
            )
          })}
          <SelectSeparator />
          <SelectItem value={SKIP}>Don't import</SelectItem>
        </SelectContent>
      </Select>
    </div>
  )
}

import { Check, CircleAlert, Copy } from 'lucide-react'
import type { ColumnDef, Table } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import { Checkbox } from '#/components/ui/checkbox'
import { MappingSelect } from './mapping-select'
import { ReviewCell } from './review-cell'
import { inView } from './review'
import type { Mapping, ReviewRow, View } from './review'
import { fieldById } from './schema'
import type { FieldId } from './schema'

export interface ReviewMeta {
  mapping: Mapping
  setField: (column: number, field: FieldId | null) => void
  setCell: (rowId: string, column: number, value: string) => void
  setSkipped: (rowIds: string[], skipped: boolean) => void
}

const getMeta = (table: Table<ReviewRow>) =>
  table.options.meta as unknown as ReviewMeta

const statusBadge = {
  ready: { label: 'Ready', icon: Check, className: '' },
  invalid: {
    label: 'Needs fixing',
    icon: CircleAlert,
    className: 'border-destructive/40 text-destructive',
  },
  duplicate: {
    label: 'Duplicate',
    icon: Copy,
    className: 'border-amber-500/50 text-amber-700 dark:text-amber-400',
  },
  skipped: { label: 'Skipped', icon: null, className: 'text-muted-foreground' },
}

/** One column per CSV column, so the table always matches the file */
export function buildColumns(headers: string[]): ColumnDef<ReviewRow>[] {
  return [
    {
      id: 'include',
      header: ({ table }) => {
        const { setSkipped } = getMeta(table)
        const rows = table.getFilteredRowModel().rows
        const included = rows.filter((r) => r.original.status !== 'skipped')
        return (
          <Checkbox
            checked={
              included.length === 0
                ? false
                : included.length === rows.length
                  ? true
                  : 'indeterminate'
            }
            onCheckedChange={(on) =>
              setSkipped(
                rows.map((r) => r.id),
                on !== true,
              )
            }
            aria-label="Import every row shown"
          />
        )
      },
      cell: ({ row, table }) => (
        <Checkbox
          checked={row.original.status !== 'skipped'}
          onCheckedChange={(on) =>
            getMeta(table).setSkipped([row.id], on !== true)
          }
          aria-label={`Import line ${row.original.line}`}
        />
      ),
    },
    {
      id: 'line',
      header: () => <span className="text-xs font-normal">Line</span>,
      cell: ({ row }) => (
        <span className="text-xs text-muted-foreground tabular-nums">
          {row.original.line}
        </span>
      ),
    },
    ...headers.map((header, column): ColumnDef<ReviewRow> => ({
      id: `col-${column}`,
      header: ({ table }) => {
        const meta = getMeta(table)
        return (
          <MappingSelect
            header={header}
            column={column}
            mapping={meta.mapping}
            onChange={(field) => meta.setField(column, field)}
          />
        )
      },
      cell: ({ row, table }) => {
        const meta = getMeta(table)
        const field = meta.mapping[column]
        const value = row.original.cells[column]
        // Columns that aren't imported are shown for context only
        if (!field) {
          return (
            <span className="block max-w-48 truncate px-2 text-muted-foreground/70">
              {value}
            </span>
          )
        }
        return (
          <ReviewCell
            value={value}
            issue={row.original.issues[column]}
            label={`${fieldById[field].label}, line ${row.original.line}`}
            onCommit={(next) => meta.setCell(row.id, column, next)}
          />
        )
      },
    })),
    {
      id: 'status',
      accessorFn: (row) => row.status,
      filterFn: (row, _id, view: View) => inView(row.original.status, view),
      header: () => <span className="text-xs font-normal">Status</span>,
      cell: ({ row }) => {
        const badge = statusBadge[row.original.status]
        const Icon = badge.icon
        const count = Object.keys(row.original.issues).length
        return (
          <Badge variant="outline" className={badge.className}>
            {Icon ? <Icon className="size-3" /> : null}
            {row.original.status === 'invalid' && count > 1
              ? `${count} problems`
              : badge.label}
          </Badge>
        )
      },
    },
  ]
}

import { useMemo } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  useReactTable,
} from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { TooltipProvider } from '#/components/ui/tooltip'
import { cn } from '#/lib/utils'
import { buildColumns } from './columns'
import type { ReviewMeta } from './columns'
import type { ReviewRow, View } from './review'

export function ReviewTable({
  headers,
  rows,
  view,
  meta,
}: {
  headers: string[]
  rows: ReviewRow[]
  view: View
  meta: ReviewMeta
}) {
  const columns = useMemo(() => buildColumns(headers), [headers])
  // A stable array: a new one each render would recompute the filtered rows
  // every time, and with them TanStack's automatic page reset
  const columnFilters = useMemo(
    () => (view === 'all' ? [] : [{ id: 'status', value: view }]),
    [view],
  )

  const table = useReactTable({
    data: rows,
    columns,
    // Row ids are the row's position in the file, so edits never move or reset a row
    getRowId: (row) => row.id,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    state: { columnFilters },
    // No pagination here, so edits have no page to reset
    autoResetPageIndex: false,
    meta,
  })

  const visible = table.getRowModel().rows

  return (
    <TooltipProvider delayDuration={150}>
      <div className="rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className="hover:bg-transparent">
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id} className="h-auto align-bottom">
                    <div className="flex min-h-9 items-center">
                      {flexRender(
                        header.column.columnDef.header,
                        header.getContext(),
                      )}
                    </div>
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {visible.length ? (
              visible.map((row) => (
                <TableRow
                  key={row.id}
                  className={cn(
                    row.original.status === 'skipped' &&
                      '[&>td:not(:first-child)]:opacity-50',
                  )}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className="py-1.5">
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow className="hover:bg-transparent">
                <TableCell
                  colSpan={columns.length}
                  className="h-24 text-center text-muted-foreground"
                >
                  {view === 'attention'
                    ? 'Nothing left to fix.'
                    : view === 'skipped'
                      ? 'No rows are skipped.'
                      : 'No rows here.'}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
    </TooltipProvider>
  )
}

import { useMemo, useRef, useState } from 'react'
import { CircleAlert, CircleCheck, FileSpreadsheet, Upload } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils'
import { parseCsv } from './csv'
import type { CsvData } from './csv'
import { ReviewTable } from './data-table'
import {
  assign,
  autoMap,
  inView,
  missingRequired,
  review,
  toRecords,
} from './review'
import type { CustomerRecord, Mapping, View } from './review'
import { sampleCsv } from './sample'

interface ImportFile {
  name: string
  csv: CsvData
  mapping: Mapping
}

const sample = (): ImportFile => {
  const csv = parseCsv(sampleCsv)
  return { name: 'customers-export.csv', csv, mapping: autoMap(csv.headers) }
}

const views: { id: View; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'attention', label: 'Needs fixing' },
  { id: 'ready', label: 'Ready' },
  { id: 'skipped', label: 'Skipped' },
]

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

export function CsvImportDemo() {
  const [file, setFile] = useState<ImportFile>(sample)
  const [skipped, setSkippedIds] = useState<ReadonlySet<string>>(new Set())
  const [view, setView] = useState<View>('all')
  const [error, setError] = useState<string | null>(null)
  const [imported, setImported] = useState<CustomerRecord[] | null>(null)
  const input = useRef<HTMLInputElement>(null)

  const rows = useMemo(
    () => review(file.csv, file.mapping, skipped),
    [file, skipped],
  )
  const missing = missingRequired(file.mapping)
  const count = (v: View) => rows.filter((r) => inView(r.status, v)).length
  const ready = count('ready')
  const attention = count('attention')

  function load(next: ImportFile) {
    setFile(next)
    setSkippedIds(new Set())
    setView('all')
    setError(null)
    setImported(null)
  }

  async function upload(chosen: File | undefined) {
    if (!chosen) return
    try {
      const csv = parseCsv(await chosen.text())
      load({ name: chosen.name, csv, mapping: autoMap(csv.headers) })
    } catch (e) {
      setError(e instanceof Error ? e.message : 'This file could not be read.')
    }
  }

  const meta = {
    mapping: file.mapping,
    setField: (column: number, field: Mapping[number]) =>
      setFile((f) => ({ ...f, mapping: assign(f.mapping, column, field) })),
    setCell: (rowId: string, column: number, value: string) =>
      setFile((f) => ({
        ...f,
        csv: {
          ...f.csv,
          rows: f.csv.rows.map((cells, i) =>
            String(i) === rowId
              ? cells.map((c, j) => (j === column ? value : c))
              : cells,
          ),
        },
      })),
    setSkipped: (ids: string[], skip: boolean) =>
      setSkippedIds((current) => {
        const next = new Set(current)
        for (const id of ids) {
          if (skip) next.add(id)
          else next.delete(id)
        }
        return next
      }),
  }

  if (imported) {
    return (
      <div className="flex flex-col items-start gap-3 rounded-md border p-6">
        <CircleCheck className="size-6 text-emerald-600" />
        <div>
          <p className="font-medium">
            Imported {plural(imported.length, 'customer')}
          </p>
          <p className="text-sm text-muted-foreground">
            Values were cleaned up on the way in: emails lowercased, plans and
            country codes in canonical form, seats as numbers.
          </p>
        </div>
        <pre className="max-h-48 w-full overflow-auto rounded-md bg-muted p-3 text-xs">
          {JSON.stringify(imported.slice(0, 2), null, 2)}
        </pre>
        <Button variant="outline" size="sm" onClick={() => load(sample())}>
          Start over
        </Button>
      </div>
    )
  }

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="flex min-w-0 items-center gap-2 text-sm">
          <FileSpreadsheet className="size-4 shrink-0 text-muted-foreground" />
          <span className="truncate font-medium">{file.name}</span>
          <span className="shrink-0 text-muted-foreground">
            {plural(rows.length, 'row')}
          </span>
        </p>
        <div className="flex gap-2">
          <Button variant="ghost" size="sm" onClick={() => load(sample())}>
            Use sample file
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => input.current?.click()}
          >
            <Upload /> Upload CSV
          </Button>
          <input
            ref={input}
            type="file"
            accept=".csv,text/csv"
            className="sr-only"
            tabIndex={-1}
            aria-hidden
            onChange={(e) => {
              void upload(e.target.files?.[0])
              e.target.value = ''
            }}
          />
        </div>
      </div>

      {error ? (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      ) : null}

      {missing.length ? (
        <p
          role="status"
          className="flex items-center gap-2 rounded-md border border-destructive/30 bg-destructive/5 px-3 py-2 text-sm text-destructive"
        >
          <CircleAlert className="size-4 shrink-0" />
          Choose a column for {missing.map((f) => f.label).join(' and ')} in the
          table header before importing.
        </p>
      ) : null}

      <div className="flex flex-wrap items-center justify-between gap-2">
        <div
          role="group"
          aria-label="Show rows"
          className="inline-flex rounded-md border p-0.5"
        >
          {views.map((v) => (
            <button
              key={v.id}
              type="button"
              aria-pressed={view === v.id}
              onClick={() => setView(v.id)}
              className="flex h-7 items-center gap-1.5 rounded px-2.5 text-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-pressed:bg-muted aria-pressed:text-foreground"
            >
              {v.label}
              <span
                className={cn(
                  'text-xs tabular-nums',
                  v.id === 'attention' && attention > 0 && 'text-destructive',
                )}
              >
                {count(v.id)}
              </span>
            </button>
          ))}
        </div>
        {attention > 0 ? (
          <Button
            variant="ghost"
            size="sm"
            onClick={() =>
              meta.setSkipped(
                rows
                  .filter((r) => inView(r.status, 'attention'))
                  .map((r) => r.id),
                true,
              )
            }
          >
            Skip {plural(attention, 'row')} with problems
          </Button>
        ) : null}
      </div>

      <ReviewTable
        headers={file.csv.headers}
        rows={rows}
        view={view}
        meta={meta}
      />

      <div className="flex flex-wrap items-center justify-between gap-3">
        <p aria-live="polite" className="text-sm text-muted-foreground">
          {ready} of {plural(rows.length, 'row')} ready.
          {attention > 0
            ? ` ${plural(attention, 'row')} with problems won't be imported until fixed or skipped.`
            : ''}
        </p>
        <Button
          size="sm"
          disabled={missing.length > 0 || ready === 0}
          onClick={() => setImported(toRecords(rows, file.mapping))}
        >
          Import {plural(ready, 'customer')}
        </Button>
      </div>
    </div>
  )
}
